import argparse
import json
from pathlib import Path
import re


def reject_constant(value):
    raise ValueError('invalid JSON constant: ' + value)


def summarize(node):
    channels, bad = {}, []
    state = None
    if (node / 'state.json').exists():
        try:
            state = json.loads((node / 'state.json').read_text(), parse_constant=reject_constant)
            if not isinstance(state, dict):
                raise ValueError()
        except (ValueError, OSError):
            bad.append(dict(file='state.json', line=None, why='bad_state'))
    state_bad = bool(bad)
    for ch in ('obs', 'must'):
        paths = sorted((p for p in node.iterdir() if p.is_file() and not p.is_symlink() and re.fullmatch(ch + r'\.\d{12}\.jsonl', p.name)), key=lambda p: int(p.name.split('.')[1]))
        active = node / (ch + '.active.jsonl')
        if active.is_file() and not active.is_symlink():
            paths.append(active)
        seqs = []
        for p in paths:
            raw = p.read_bytes()
            lines = raw.split(b'\n')
            for i, part in enumerate(lines if lines[-1] else lines[:-1], 1):
                line = part + b'\n' if i < len(lines) else part
                why = None
                if not line.endswith(b'\n'):
                    why = 'torn'
                else:
                    try:
                        rec = json.loads(line, parse_constant=reject_constant)
                        if not isinstance(rec, dict) or type(rec.get('seq')) is not int or rec['seq'] < 1:
                            why = 'no_seq'
                        else:
                            seqs.append(rec['seq'])
                    except (ValueError, UnicodeError):
                        why = 'bad_json'
                if why:
                    bad.append(dict(file=p.relative_to(node).as_posix(), line=i, why=why))
        unique = sorted(set(seqs))
        missing = []
        for a, b in zip(unique, unique[1:]):
            if b > a + 1:
                missing.append([a + 1, b - 1])
        first, last = (unique[0], unique[-1]) if unique else (None, None)
        next_seq = unacked = stale = None
        if state is not None:
            try:
                s = state['channels'][ch]
                if type(s['next_seq']) is not int or (ch == 'must' and type(s['acked_upto']) is not int):
                    raise ValueError()
                next_seq = s['next_seq']
                unacked = sum(x > s['acked_upto'] for x in unique) if ch == 'must' else None
                stale = next_seq != last + 1 if last is not None else None
            except (KeyError, TypeError, ValueError):
                state_bad = True
        channels[ch] = dict(count=len(seqs), first=first, last=last, missing=missing,
                            dup=[x for x in unique if seqs.count(x) >= 2],
                            next_seq=next_seq, unacked=unacked, stale_next=stale)
    if state_bad and not any(x['why'] == 'bad_state' for x in bad):
        bad.append(dict(file='state.json', line=None, why='bad_state'))
    return dict(v=1, channels=channels, bad=sorted(bad, key=lambda x: (x['file'], x['line'] or 0, x['why'])))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('node', type=Path)
    a = ap.parse_args()
    if not a.node.is_dir():
        return 2
    print(json.dumps(summarize(a.node)))
    return 0
